Rules.InvariantScript:
Select(Parent);
Set(varFormMode, "Edit");
Set(varSelectedIssue, ThisItem);
Navigate(
    'Report Issue Screen',
    ScreenTransition.None,
    {
        screenType: "Edit",
        selectedPerson: If(
            IsBlank(ThisItem.'Assigned to'.Email),
            Blank(),
            First(Office365Users.SearchUser({searchTerm: ThisItem.'Assigned to'.Email, top: 1}))
        )
    }
)
